  "id": "subsec-moisturizers-use-emulsifiers-with-varying-oil-to-water-ratios-6",
  "level": "2",
  "url": "sec-moisturizers-and-lotions.html#subsec-moisturizers-use-emulsifiers-with-varying-oil-to-water-ratios-6",
